package worker_test
import("context";"errors";"io";"log/slog";"testing";"time";"github.com/11DingKing/robotcell-lifecycle-control/internal/recovery";"github.com/11DingKing/robotcell-lifecycle-control/internal/worker")
func TestWorkerRetryUsesBackoff(t *testing.T){db,manual:=workerStore(t); job:=createJob(t,db,manual.Now(),"retry-backoff","calibration_compensation",3); w:=worker.New(db,manual,slog.New(slog.NewTextHandler(io.Discard,nil)),"retry",time.Millisecond,time.Second); w.Register(job.Kind,func(context.Context,recovery.Job)error{return errors.New("temporary")}); ctx,cancel:=context.WithTimeout(context.Background(),10*time.Millisecond); defer cancel(); w.Run(ctx); got,err:=db.FindRecoveryByKey(context.Background(),job.IdempotencyKey); if err!=nil{t.Fatal(err)}; want:=manual.Now().Add(time.Second); if got.Status!=recovery.RetryWait||!got.NextAttemptAt.Equal(want){t.Fatalf("retry backoff=%v status=%s",got.NextAttemptAt,got.Status)} }
